const std = @import("std");
const utils = @import("utils");
const CliArgs = @import("CliArgs");
const Program = @import("Program");
const Lexer = @import("Lexer");
const Parser = @import("Parser");
const Codegen = @import("Codegen");

fn codegenContent(content: []const u8) ![]const u8 {
    const alloc = std.testing.allocator;
    const io = std.testing.io;

    try utils.init(alloc, io);
    defer utils.deinit();
    defer utils.deinitStrings();

    utils.setFlags(.{ .quiet = true, .no_warnings = true });

    const program = try utils.alloc.create(Program);
    defer utils.alloc.destroy(program);

    program.init(content, "test.asm");
    defer {
        program.tokens.deinit(utils.alloc);
        program.code_block.operands.deinit(utils.alloc);
        program.code_block.instr.deinit(utils.alloc);
        program.data_buffer.deinit(utils.alloc);
        program.code_block.buffer.deinit(utils.alloc);
        program.shared_libs.deinit(utils.alloc);
        program.data_vars.deinit(utils.alloc);
        var func_iter = program.funcs.iterator();
        while (func_iter.next()) |func| {
            func.value_ptr.local_labels.deinit(utils.alloc);
        }
        program.funcs.deinit(utils.alloc);
        program.imports.deinit(utils.alloc);
        program.relocations.deinit(utils.alloc);
        program.line_program.deinit(utils.alloc);
    }

    var lexer = Lexer.init(program);
    try lexer.tokenizeContent();

    var parser = Parser.init(program);
    try parser.parseTokens();

    var codegen = Codegen.init(program);
    defer codegen.deinit();
    try codegen.generateCode();

    return utils.alloc.dupe(u8, program.code_block.buffer.items);
}

test "movdqa" {
    const content: []const u8 =
        \\@data
        \\label: d32 0x455
        \\@code
        \\movdqa xmm0, xmm1
        \\movdqa xmm1, xmm15
        \\movdqa xmm10, xmm1
        \\movdqa xmm14, xmm13
        \\movdqa xmm6, [r12*4]
        \\movdqa xmm12, [rbp*2]
        \\movdqa xmm0, [esp + 4]
        \\movdqa xmm8, [rcx + rdx*8]
        \\movdqa xmm1, [rbp - 3564]
        \\movdqa xmm2, [label - 4]
        \\movdqa [label + 12], xmm1
        \\movdqa [esp + 888], xmm14
        \\
    ;

    const actual = codegenContent(content) catch |err| {
        utils.handleError(err);
        return;
    };
    defer utils.alloc.free(actual);

    const expected: []const u8 = &.{ 0x66, 0x0F, 0x6F, 0xC1, 0x66, 0x41, 0x0F, 0x6F, 0xCF, 0x66, 0x44, 0x0F, 0x6F, 0xD1, 0x66, 0x45, 0x0F, 0x6F, 0xF5, 0x66, 0x42, 0x0F, 0x6F, 0x34, 0xA5, 0x00, 0x00, 0x00, 0x00, 0x66, 0x44, 0x0F, 0x6F, 0x24, 0x6D, 0x00, 0x00, 0x00, 0x00, 0x67, 0x66, 0x0F, 0x6F, 0x44, 0x24, 0x04, 0x66, 0x44, 0x0F, 0x6F, 0x04, 0xD1, 0x66, 0x0F, 0x6F, 0x8D, 0x14, 0xF2, 0xFF, 0xFF, 0x66, 0x0F, 0x6F, 0x15, 0x00, 0x00, 0x00, 0x00, 0x66, 0x0F, 0x7F, 0x0D, 0x00, 0x00, 0x00, 0x00, 0x67, 0x66, 0x44, 0x0F, 0x7F, 0xB4, 0x24, 0x78, 0x03, 0x00, 0x00 };

    try std.testing.expectEqualSlices(u8, expected, actual);
}

test "mov" {
    const content: []const u8 =
        \\@data
        \\label: d32 0x455
        \\@code
        \\mov al, [esp + 4]
        \\mov r8b, [rbp - 3564]
        \\mov eax, [label - 4]
        \\mov rdx, r8
        \\mov r9, [rbp*2]
        \\mov r12, [r12*4]
        \\
    ;

    const actual = codegenContent(content) catch |err| {
        utils.handleError(err);
        return;
    };
    defer utils.alloc.free(actual);

    const expected: []const u8 = &.{ 0x67, 0x8A, 0x44, 0x24, 0x04, 0x44, 0x8A, 0x85, 0x14, 0xF2, 0xFF, 0xFF, 0x8B, 0x05, 0x00, 0x00, 0x00, 0x00, 0x49, 0x8B, 0xD0, 0x4C, 0x8B, 0x0C, 0x6D, 0x00, 0x00, 0x00, 0x00, 0x4E, 0x8B, 0x24, 0xA5, 0x00, 0x00, 0x00, 0x00 };

    try std.testing.expectEqualSlices(u8, expected, actual);
}

